diff --git a/CHANGELOG.md b/CHANGELOG.md
index 99bfa5661..10bf09372 100644
--- a/CHANGELOG.md
+++ b/CHANGELOG.md
@@ -13,6 +13,17 @@ block a release again.

 ## Unreleased

+- fix(stuck-calls): gh-1632 — a stuck tool call in an interactive session now
+  escalates like everywhere else. `effectiveStuckTool()` defaulted every
+  non-headless host to `StuckFollowUpMode.advisory` when no explicit
+  `agent.stuckTool:` was configured, so the fa 1.0.580 incident session (a
+  dead `git fetch` in the REPL) fired its `tool_stuck` flag at the 300 s
+  threshold and then hung for 27 more minutes — advisory mode never cancels,
+  retries, or converts; only the owner's manual steering broke the deadlock.
+  The autonomous default (cancel → retry once → background-convert, then a
+  session-visible escalation) now applies in EVERY mode; `advisory` remains
+  an explicit opt-out (`agent.stuckTool.followUp: advisory`), never an
+  implicit default.
 - fix(bindings): gh-1624 — the gh-1570 binding preflight no longer kills
   translating-proxy factories. `_validateModelEndpoint`'s vendor-prefix
   verdict was fatal on ANY endpoint, so `FA_PROVIDER_TYPE=anthropic` +
diff --git a/lib/src/agent/agent_loop.dart b/lib/src/agent/agent_loop.dart
index 1fbb278c3..9201e33b3 100644
--- a/lib/src/agent/agent_loop.dart
+++ b/lib/src/agent/agent_loop.dart
@@ -857,8 +857,10 @@ final class ToolCallHeartbeatEvent extends AgentEvent {

 /// What the stuck-call follow-up did (or decided) at the threshold.
 enum StuckFollowUpAction {
-  /// Advisory only (interactive mode): the threshold was hit, nothing was
-  /// cancelled.
+  /// The threshold was hit and the configured follow-up mode is
+  /// `advisory` (an explicit `agent.stuckTool.followUp: advisory`
+  /// opt-out — gh-1632 removed the implicit interactive default):
+  /// nothing was cancelled.
   advisory,

   /// The stuck call was cancelled and is being retried once (marked).
diff --git a/lib/src/agent/agent_loop_stuck_supervision.dart b/lib/src/agent/agent_loop_stuck_supervision.dart
index 113a8f6d9..1788abcae 100644
--- a/lib/src/agent/agent_loop_stuck_supervision.dart
+++ b/lib/src/agent/agent_loop_stuck_supervision.dart
@@ -167,8 +167,10 @@ ToolExecutionResult _prefixMarks(
 ///   result is a marked error. Never die silently.
 ///
 /// Advisory mode ([StuckFollowUpMode.advisory]) stops after the advisory
-/// stuck event: nothing is ever cancelled (interactive sessions with a
-/// human present).
+/// stuck event: nothing is ever cancelled. It is an explicit opt-out
+/// (`agent.stuckTool.followUp: advisory`) — never an implicit default:
+/// gh-1632 removed the interactive-advisory default after the incident
+/// session hung 27 minutes on a dead call with only the flag emitted.
 /// The follow-up stage an attempt is supervised under: attempt 1 is
 /// cancelled and retried once; from attempt 2 on a further hang converts
 /// to a background job before escalating.
diff --git a/lib/src/agent/stuck_tool.dart b/lib/src/agent/stuck_tool.dart
index 33fd85744..43110aa5c 100644
--- a/lib/src/agent/stuck_tool.dart
+++ b/lib/src/agent/stuck_tool.dart
@@ -47,9 +47,10 @@ const defaultStuckHeartbeatSeconds = 60;
 const defaultStuckCancelGraceSeconds = 10;

 /// How the threshold follow-up behaves: [autonomous] cancels/retries/
-/// converts (headless parity — the mode-independent default), [advisory]
-/// only emits the advisory stuck event (interactive comfort; kill switch
-/// for the autonomy).
+/// converts and is THE default in EVERY mode — headless and interactive
+/// alike (gh-1632 I1); [advisory] only emits the advisory stuck event and
+/// exists solely as an explicit opt-out
+/// (`agent.stuckTool.followUp: advisory`).
 enum StuckFollowUpMode { autonomous, advisory }

 /// The cancel reason the stuck supervisor puts on a call/yield token — a
