    maxRatio,
    greaterThan(_minGrowthRatio),
    reason:
        '$label doubling ratio never exceeded ${_minGrowthRatio}x '
        '(${maxRatio.toStringAsFixed(2)}x across $_growthAttempts '
        'attempts) — the measurement is degenerate and asserts nothing',
  );
}

