double medianWrapMs(
  String line,
  int width, {
  int runs = 5,
  ElapsedUs? elapsedUs,
}) {
  final measure = elapsedUs ?? _stopwatchUs;
  wrapAnsiLine(line, width); // JIT warm-up, untimed
  final times = List<double>.filled(runs, 0);
  for (var i = 0; i < runs; i++) {
    times[i] = measure(() => wrapAnsiLine(line, width)) / 1000.0;
  }
  times.sort();
  return times[runs ~/ 2];
